export const defaults={type:'Кухня',layout:'Прямая',width:3200,height:2600,depth:600,finish:'Шалфей',extras:[],city:'',name:'',notes:'',budget:'Обсудим'};
export function validateDimensions(p){return ['width','height','depth'].some(k=>!Number.isFinite(Number(p[k]))||Number(p[k])<({width:600,height:500,depth:200}[k])||Number(p[k])>({width:10000,height:3500,depth:1200}[k]))?'Проверьте размеры: ширина 600–10000, высота 500–3500, глубина 200–1200 мм.':'';}
export function buildBrief(p){return `Вадим, здравствуйте! Хочу обсудить мебель на заказ.\n\nИмя: ${p.name||'Пока не указано'}\nГород: ${p.city||'Уточню'}\nТип: ${p.type}\nПланировка: ${p.layout}\nРазмеры Ш × В × Г: ${p.width} × ${p.height} × ${p.depth} мм\nОтделка: ${p.finish} (ориентир по цвету)\nПожелания к наполнению: ${p.extras.length?p.extras.join(', '):'Обсудим'}\nОриентир по бюджету: ${p.budget}\nДополнительно: ${p.notes||'Обсудим при знакомстве'}\n\nРазмеры предварительные. Прошу уточнить материалы, возможность изготовления, стоимость и сроки.`;}
export function restoreDraft(raw){try{const d=JSON.parse(raw);if(d.version!==2||!d.project||!['Кухня','Шкаф','Гардеробная'].includes(d.project.type))return null;const p={...defaults,...d.project};if(validateDimensions(p)||!Array.isArray(p.extras)||p.extras.some(x=>typeof x!=='string'))return null;for(const k of ['layout','finish','name','city','notes','budget'])if(typeof p[k]!=='string')return null;return p;}catch{return null;}}
